DCMotor m1(8, 9);   // IN1 on Line B, IN2 on Line A (as studio wires it)
DCMotor m6(12, 13);   // IN1 on Line B, IN2 on Line A (as studio wires it)
DCMotor m9(41, 40);   // IN1 on Line B, IN2 on Line A (as studio wires it)
DCMotor m14(35, 36);   // IN1 on Line B, IN2 on Line A (as studio wires it)
VL53L5CX_Sensor distance_sensor(Wire);
bool distance_sensor_ok = false;

// ---- user globals ----
// ===== motion (owner: Sara). Reference host-tested copy: firmware/robot/motion.cpp =====
// FRONT = end where the distance sensor (port 7) faces = end opposite the USB-C.
// Facing front: LEFT side = ports 6,1 ; RIGHT side = ports 14,9.
// Measured: +speed on 6,1 pushes toward USB (= backward), on 14,9 toward front.
static const int SIGN_LEFT  = -1;   // ports 6, 1
static const int SIGN_RIGHT = +1;   // ports 14, 9
static const bool COL_FLIP  = false; // flip if bearing is mirrored (test with a hand)

static const int OBSTACLE_STOP_MM = 250, FOLLOW_MM = 400, FOLLOW_NEAR_MM = 300, FOLLOW_FAR_MM = 1200;
static const int MIN_PWM = 170, CRUISE = 190, TURN_SPEED = 180, RAMP_PER_S = 500;
static const int CLEAR_MM = OBSTACLE_STOP_MM + 150;
static const unsigned long TURN_MIN_MS = 400, TURN_MAX_MS = 2500, COME_HOLD_MS = 500;
static const unsigned long WATCHDOG_MS = 2000, STATE_MS = 1000;
enum Mode { M_IDLE, M_WALK, M_FOLLOW, M_COME, M_STOP, M_MANUAL };
static const char* MODE_NAMES[] = {"idle","walk","follow","come","stop","manual"};
static Mode g_mode = M_IDLE;
static float cur_l = 0, cur_r = 0;
static int tgt_l = 0, tgt_r = 0;
static unsigned long last_ms = 0, last_state_ms = 0, last_rx = 0;
static bool armed = false, out_nonzero = false, turning = false, wd_tripped = false;
static int turn_dir = 1;
static unsigned long turn_start = 0, come_since = 0;

struct Range { int left_mm, right_mm, min_mm; float bearing; bool blocked, valid; };

static int clampi(int v, int lo, int hi) { return v < lo ? lo : (v > hi ? hi : v); }

// Local stand-in for Reshma's range_get(): 8x8 grid -> left/right halves + bearing.
static Range range_get() {
  Range r = {4000, 4000, 4000, 0, false, false};
  if (!distance_sensor_ok || !distance_sensor.isReady()) return r;
  int16_t g[64]; distance_sensor.getDistanceGrid(g);
  int best = 4000, bestc = 3;
  for (int row = 1; row < 7; row++) for (int c = 0; c < 8; c++) {
    int d = g[row * 8 + c];
    if (d <= 0 || d >= 4000) continue;
    if (c < 4) { if (d < r.left_mm) r.left_mm = d; } else { if (d < r.right_mm) r.right_mm = d; }
    if (d < best) { best = d; bestc = c; }
  }
  if (COL_FLIP) { int t = r.left_mm; r.left_mm = r.right_mm; r.right_mm = t; bestc = 7 - bestc; }
  r.min_mm = best;
  r.bearing = (bestc - 3.5f) / 3.5f;
  r.blocked = best < OBSTACLE_STOP_MM;
  r.valid = true;
  return r;
}

static void hw_write(int left, int right) {   // left/right in robot frame, -255..255
  left *= SIGN_LEFT; right *= SIGN_RIGHT;
  m6.setSpeed(left);  m1.setSpeed(left);
  m14.setSpeed(right); m9.setSpeed(right);
}
static void set_target(int l, int r) { tgt_l = clampi(l, -255, 255); tgt_r = clampi(r, -255, 255); }
static int apply_min_pwm(float v) {
  if (v > -0.5f && v < 0.5f) return 0;
  float a = v < 0 ? -v : v;
  int o = MIN_PWM + (int)(a * (255 - MIN_PWM) / 255.0f);
  return v < 0 ? -o : o;
}
static void motion_stop() { tgt_l = tgt_r = 0; cur_l = cur_r = 0; hw_write(0, 0); out_nonzero = false; }
static void set_mode(Mode m) {
  if (m == g_mode) return;
  g_mode = m; turning = false; come_since = 0;
  if (m == M_IDLE || m == M_STOP) motion_stop();
}
static bool set_mode_name(const String& n) {
  if (n == "idle") set_mode(M_IDLE); else if (n == "walk") set_mode(M_WALK);
  else if (n == "follow") set_mode(M_FOLLOW); else if (n == "come") set_mode(M_COME);
  else if (n == "stop") set_mode(M_STOP); else return false;
  return true;
}

static void do_walk(const Range& r, unsigned long now) {
  if (turning) {
    if ((now - turn_start >= TURN_MIN_MS && r.min_mm >= CLEAR_MM) || now - turn_start >= TURN_MAX_MS) turning = false;
    else { set_target(turn_dir * TURN_SPEED, -turn_dir * TURN_SPEED); return; }
  }
  if (r.blocked) {
    turning = true; turn_start = now;
    turn_dir = (r.left_mm > r.right_mm) ? -1 : 1;   // toward the freer side (+1 = turn right)
    set_target(0, 0); cur_l = cur_r = 0; return;
  }
  set_target(CRUISE, CRUISE);
}
static bool do_follow(const Range& r) {
  if (r.min_mm < FOLLOW_NEAR_MM - 100 || r.min_mm > FOLLOW_FAR_MM) { set_target(0, 0); return false; }
  int err = r.min_mm - FOLLOW_MM;
  int fwd = abs(err) < 50 ? 0 : clampi(err / 4, 0, CRUISE);
  int steer = (int)(r.bearing * 100.0f);
  if (abs(steer) < 12) steer = 0;
  set_target(fwd + steer, fwd - steer);
  return true;
}
static void do_come(const Range& r, unsigned long now) {
  bool t = do_follow(r);
  if (t && abs(r.min_mm - FOLLOW_MM) < 60) {
    if (!come_since) come_since = now;
    if (now - come_since >= COME_HOLD_MS) set_mode(M_IDLE);
  } else come_since = 0;
}
static void ramp(float& c, int t, float step) {
  if (c < t) { c += step; if (c > t) c = t; } else if (c > t) { c -= step; if (c < t) c = t; }
}
static void motion_tick() {
  unsigned long now = millis();
  float dt = (now - last_ms) / 1000.0f; if (dt > 0.1f) dt = 0.1f; last_ms = now;
  Range r = range_get();
  if (armed && now - last_rx > WATCHDOG_MS) {            // laptop silent -> stop
    if (!wd_tripped) { motion_stop(); g_mode = M_IDLE; wd_tripped = true; }
  } else {
    wd_tripped = false;
    bool needs_sensor = (g_mode == M_WALK || g_mode == M_FOLLOW || g_mode == M_COME);
    if (needs_sensor && !r.valid) set_target(0, 0);      // never drive blind
    else switch (g_mode) {
      case M_WALK: do_walk(r, now); break;
      case M_FOLLOW: do_follow(r); break;
      case M_COME: do_come(r, now); break;
      case M_IDLE: case M_STOP: set_target(0, 0); break;
      case M_MANUAL: break;
    }
    if (r.valid && r.blocked) {                          // safety: no forward motion < stop dist
      int f = (tgt_l + tgt_r) / 2; if (f > 0) { tgt_l -= f; tgt_r -= f; }
      float cf = (cur_l + cur_r) / 2; if (cf > 0) { cur_l -= cf; cur_r -= cf; }
    }
    float step = RAMP_PER_S * dt;
    ramp(cur_l, tgt_l, step); ramp(cur_r, tgt_r, step);
    int ol = apply_min_pwm(cur_l), orr = apply_min_pwm(cur_r);
    hw_write(ol, orr);
    out_nonzero = (ol != 0 || orr != 0);
  }
  if (now - last_state_ms >= STATE_MS) {
    last_state_ms = now;
    Serial.printf("{\"type\":\"event\",\"payload\":{\"event_type\":\"sensor\",\"key\":\"robot_state\",\"value\":\"%s,%d,%d,%d,%d\"}}\n",
                  MODE_NAMES[g_mode], out_nonzero ? 1 : 0, r.valid ? r.min_mm : -1, r.left_mm, r.right_mm);
  }
}

// ---- atech actions (host -> board) ----
// `atech send <key> [value]` / board.call(key, value). Module actions are dispatched
// below. For your own action, test `atech_action` in code.loop and call atechDone():
//   if (atech_action == "buzz") { spk.playTone(880, 100); atechDone(); }
String atech_action;   // key of the action waiting for user code ("" = none)
String atech_value;    // its value
static String _atech_line;
static const char* _atech_error = nullptr;

// Call from a handler (or code.loop) when the action could not be carried out:
// the host then gets ok:false with this message instead of a false success.
static void atechFail(const char* why) { _atech_error = why; }

static String atechJsonString(const String& json, const char* field, int from = 0, int* endOut = nullptr) {
    String pat = String("\"") + field + "\":";
    int i = json.indexOf(pat, from);
    if (i < 0) return String();
    i += pat.length();
    while (i < (int)json.length() && json[i] == ' ') i++;
    if (i >= (int)json.length() || json[i] != '"') return String();
    String out;
    for (i++; i < (int)json.length(); i++) {
        char c = json[i];
        if (c == '\\' && i + 1 < (int)json.length()) {
            char n = json[++i];
            out += (n == 'n') ? '\n' : (n == 't') ? '\t' : n;
        } else if (c == '"') {
            break;
        } else {
            out += c;
        }
    }
    if (endOut) *endOut = i;
    return out;
}

// Number stored under "field" in a flat JSON object, e.g. atechNum(value, "r", 0).
static long atechNum(const String& json, const char* field, long fallback) {
    String pat = String("\"") + field + "\":";
    int i = json.indexOf(pat);
    if (i < 0) return fallback;
    i += pat.length();
    while (i < (int)json.length() && (json[i] == ' ' || json[i] == '"')) i++;
    if (i >= (int)json.length() || !(isDigit(json[i]) || json[i] == '-')) return fallback;
    return json.substring(i).toInt();
}

// Number array stored under "field", e.g. {"positions":[1,2,3]}. Returns how many were read.
static int atechNums(const String& json, const char* field, long* out, int maxN) {
    String pat = String("\"") + field + "\":";
    int i = json.indexOf(pat);
    if (i < 0) return 0;
    i = json.indexOf('[', i);
    if (i < 0) return 0;
    int n = 0;
    i++;
    while (i < (int)json.length() && n < maxN) {
        while (i < (int)json.length() && (json[i] == ' ' || json[i] == ',')) i++;
        if (i >= (int)json.length() || json[i] == ']') break;
        out[n++] = json.substring(i).toInt();
        while (i < (int)json.length() && json[i] != ',' && json[i] != ']') i++;
    }
    return n;
}

static bool atechTruthy(const String& v) {
    return v == "true" || v == "1" || v == "on";
}

static void atechAck(const String& key, bool ok, const char* error = nullptr) {
    Serial.print("{\"type\":\"ack\",\"payload\":{\"action\":\"");
    Serial.print(key);
    Serial.print(ok ? "\",\"ok\":true" : "\",\"ok\":false");
    if (error) { Serial.print(",\"error\":\""); Serial.print(error); Serial.print("\""); }
    Serial.println("}}");
}

// Call from code.loop after handling `atech_action` yourself.
static void atechDone() {
    if (!atech_action.length()) return;
    atechAck(atech_action, _atech_error == nullptr, _atech_error);
    _atech_error = nullptr;
    atech_action = "";
    atech_value = "";
}

static bool atechDispatch(const String& key, const String& value) {
    if (key == "m1_speed") {
        m1.setSpeed(constrain(value.toInt(), -255, 255));
        return true;
    }
    if (key == "m1_stop") {
        m1.stop();
        return true;
    }
    if (key == "m1_brake") {
        m1.brake();
        return true;
    }
    if (key == "m6_speed") {
        m6.setSpeed(constrain(value.toInt(), -255, 255));
        return true;
    }
    if (key == "m6_stop") {
        m6.stop();
        return true;
    }
    if (key == "m6_brake") {
        m6.brake();
        return true;
    }
    if (key == "m9_speed") {
        m9.setSpeed(constrain(value.toInt(), -255, 255));
        return true;
    }
    if (key == "m9_stop") {
        m9.stop();
        return true;
    }
    if (key == "m9_brake") {
        m9.brake();
        return true;
    }
    if (key == "m14_speed") {
        m14.setSpeed(constrain(value.toInt(), -255, 255));
        return true;
    }
    if (key == "m14_stop") {
        m14.stop();
        return true;
    }
    if (key == "m14_brake") {
        m14.brake();
        return true;
    }
    return false;
}

static void atechPollAction() {
    while (Serial.available()) {
        char c = (char)Serial.read();
        if (c == '\r') continue;
        if (c != '\n') {
            if (_atech_line.length() < 4096) _atech_line += c;
            continue;
        }
        String line = _atech_line;
        _atech_line = "";
        int end = 0;
        String key = atechJsonString(line, "action", 0, &end);
        if (!key.length()) continue;           // not an action line
        String value = atechJsonString(line, "value", end);
        _atech_error = nullptr;
        if (atechDispatch(key, value)) {
            atechAck(key, _atech_error == nullptr, _atech_error);
            _atech_error = nullptr;
        } else {
            atech_action = key;                 // offered to code.loop for this pass
            atech_value = value;
        }
        return;                                 // one action per loop pass
    }
}

static void atechFinishAction() {
    if (atech_action.length()) {
        atechAck(atech_action, false, "unknown action");
        atech_action = "";
        atech_value = "";
    }
}

void setup() {
    Serial.setRxBufferSize(4096);   // room for a burst of actions from the host
    Serial.begin(115200);
    Serial.setTxTimeoutMs(0);    // Don't block when no host is listening

    m1.begin();

    m6.begin();

    m9.begin();

    m14.begin();

    Wire.begin(43, 44);
    Wire.setClock(400000);
    distance_sensor_ok = distance_sensor.begin();

    // ---- user setup ----
    last_ms = last_rx = millis();

    // ---- atech boot diagnostics (read by `atech check`) ----
    {
    esp_reset_reason_t _rr = esp_reset_reason();
    const char* _rrs;
    switch (_rr) {
        case ESP_RST_POWERON:   _rrs = "POWERON";   break;
        case ESP_RST_EXT:       _rrs = "EXT";       break;
        case ESP_RST_SW:        _rrs = "SOFTWARE";  break;
        case ESP_RST_PANIC:     _rrs = "PANIC";     break;
        case ESP_RST_INT_WDT:   _rrs = "INT_WDT";   break;
        case ESP_RST_TASK_WDT:  _rrs = "TASK_WDT";  break;
        case ESP_RST_WDT:       _rrs = "WDT";       break;
        case ESP_RST_BROWNOUT:  _rrs = "BROWNOUT";  break;
        case ESP_RST_DEEPSLEEP: _rrs = "DEEPSLEEP"; break;
        default:                _rrs = "UNKNOWN";   break;
    }
    Serial.print("{\"type\":\"boot\",\"payload\":{\"reset_reason\":\"");
    Serial.print(_rrs);
    Serial.print("\",\"free_heap\":");
    Serial.print((unsigned)ESP.getFreeHeap());
    Serial.print(",\"modules\":[");
    Serial.print("{\"instance\":\"m1\",\"module\":\"dc_motor\",\"ok\":");
    Serial.print("true");
    Serial.print(",\"detectable\":false}");
    Serial.print(",{\"instance\":\"m6\",\"module\":\"dc_motor\",\"ok\":");
    Serial.print("true");
    Serial.print(",\"detectable\":false}");
    Serial.print(",{\"instance\":\"m9\",\"module\":\"dc_motor\",\"ok\":");
    Serial.print("true");
    Serial.print(",\"detectable\":false}");
    Serial.print(",{\"instance\":\"m14\",\"module\":\"dc_motor\",\"ok\":");
    Serial.print("true");
    Serial.print(",\"detectable\":false}");
    Serial.print(",{\"instance\":\"distance_sensor\",\"module\":\"distance_sensor\",\"ok\":");
    Serial.print((distance_sensor_ok) ? "true" : "false");
    Serial.print(",\"detectable\":true}");
    Serial.println("]}}");
    }
}

void loop() {
    atechPollAction();   // one action per pass; module actions are handled here
    static unsigned long distance_sensor_last = 0;
    if (millis() - distance_sensor_last >= 500) {
      distance_sensor_last = millis();
      Serial.print("{\"type\":\"event\",\"payload\":{\"event_type\":\"sensor\",\"key\":\"distance_sensor_min_distance\",\"value\":");
      Serial.print(distance_sensor.getMinDistance());
      Serial.println(",\"unit\":\"mm\",\"source\":\"distance_sensor\"}}");
    }

    // ---- user loop ----
    // Laptop actions: robot_mode <idle|walk|follow|come|stop>, robot_drive "l,r", robot_ping
    if (atech_action.length()) {
      if (atech_action == "robot_mode") {
        last_rx = millis(); armed = true;
        if (set_mode_name(atech_value)) atechDone();
      } else if (atech_action == "robot_drive") {
        last_rx = millis(); armed = true;
        int l = 0, r = 0;
        if (sscanf(atech_value.c_str(), "%d,%d", &l, &r) == 2) {
          g_mode = M_MANUAL; turning = false; set_target(l, r); atechDone();
        }
      } else if (atech_action == "robot_ping") {
        last_rx = millis(); armed = true; atechDone();
      }
    }
    motion_tick();

    atechFinishAction(); // an action nobody handled is answered with ok:false
}
